import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static void skipToken() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        while (c > ' ') c = read();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long m = nextLong();
        skipToken();  // the password itself does not matter
        int[] order = new int[n];
        for (int i = 0; i < n; i++) order[i] = nextInt();
        if (m == 0) {
            System.out.println(1);
            return;
        }
        // Undo the attacks in reverse. spans[] at both ends of a good segment holds its length.
        int[] spans = new int[n + 2];
        long bad = (long) n * (n + 1) / 2;
        for (int t = n; t >= 1; t--) {
            int p = order[t - 1];
            int left = spans[p - 1], right = spans[p + 1], length = left + right + 1;
            spans[p] = 1;
            spans[p - left] = length;
            spans[p + right] = length;
            bad -= (long) (left + 1) * (right + 1);  // new all-good substrings through p
            if (bad < m) {
                System.out.println(t);
                return;
            }
        }
        System.out.println(1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	m := nextInt()
	nextToken() // the password itself does not matter
	order := make([]int, n)
	for i := range order {
		order[i] = int(nextInt())
	}
	if m == 0 {
		fmt.Println(1)
		return
	}
	// Undo the attacks in reverse. spans[] at both ends of a good segment holds its length.
	spans := make([]int, n+2)
	bad := int64(n) * int64(n+1) / 2
	for t := n; t >= 1; t-- {
		p := order[t-1]
		left, right := spans[p-1], spans[p+1]
		length := left + right + 1
		spans[p] = 1
		spans[p-left] = length
		spans[p+right] = length
		bad -= int64(left+1) * int64(right+1) // new all-good substrings through p
		if bad < m {
			fmt.Println(t)
			return
		}
	}
	fmt.Println(1)
}
